<?php $success=Session::flash('success'); $error=Session::flash('error'); $employees=(array)($run['employees']??[]); $status=(string)($run['status']??'DRAFT'); ?>
<?php if($success): ?><div class="alert success"><?= h($success) ?></div><?php endif; ?><?php if($error): ?><div class="alert error"><?= h($error) ?></div><?php endif; ?>
<section class="page-heading"><div><a class="back-link" href="/payroll?company=<?= h($companyId) ?>">← Back to payroll</a><p class="eyebrow">PAYROLL RUN · <?= h($status) ?></p><h2><?= h((string)($run['period']??'')) ?> payroll</h2><p class="muted"><?= count($employees) ?> employee<?= count($employees)===1?'':'s' ?> captured in this payroll run.</p></div><span class="status status-approved"><?= h($status) ?></span></section>
<section class="card"><div class="section-heading"><div><h2>Workflow</h2><p class="muted">Calculate first, then review, approve, finalize and lock the completed payroll.</p></div></div><div class="form-actions">
<?php $actions=['DRAFT'=>['calculate'=>'Calculate payroll'],'CALCULATED'=>['review'=>'Send to review'],'IN_REVIEW'=>['approve'=>'Approve payroll'],'REVIEWED'=>['approve'=>'Approve payroll'],'APPROVED'=>['finalize'=>'Finalize payroll'],'FINALIZED'=>['lock'=>'Lock payroll']]; foreach(($actions[$status]??[]) as $action=>$label): ?><form method="post" action="/payroll/action"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="company_id" value="<?= h($companyId) ?>"><input type="hidden" name="run_id" value="<?= h((string)($run['id']??'')) ?>"><input type="hidden" name="action" value="<?= h($action) ?>"><button class="button" type="submit"><?= h($label) ?></button></form><?php endforeach; ?></div></section>
<section class="card"><div class="section-heading"><div><h2>Reports</h2><p class="muted">Review payroll totals or open employee payslips.</p></div><a class="button secondary link-button" href="/reports/payroll?company=<?= rawurlencode($companyId) ?>&run=<?= rawurlencode((string)($run['id']??'')) ?>">View payroll summary</a></div></section>
<section class="table-card card"><div class="section-heading"><div><h2>Employee payroll</h2><p class="muted">Gross pay, deductions and net pay are stored against this payroll snapshot.</p></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Basic salary</th><th>Gross</th><th>PAYE</th><th>Deductions</th><th>Net pay</th><th>Status</th></tr></thead><tbody>
<?php foreach($employees as $employee): $name=trim((string)($employee['first_name']??'').' '.(string)($employee['middle_name']??'').' '.(string)($employee['last_name']??'')); ?><tr><td><strong><?= h($name) ?></strong><span class="muted"><?= h((string)($employee['employee_number']??'')) ?></span></td><td><?= h(number_format((float)($employee['basic_salary']??0),2)) ?></td><td><?= ($employee['gross_salary']??'')!=='' ? h(number_format((float)$employee['gross_salary'],2)) : '—' ?></td><td><?= ($employee['paye']??'')!=='' ? h(number_format((float)$employee['paye'],2)) : '—' ?></td><td><?= ($employee['total_deductions']??'')!=='' ? h(number_format((float)$employee['total_deductions'],2)) : '—' ?></td><td><?= ($employee['net_salary']??'')!=='' ? h(number_format((float)$employee['net_salary'],2)) : '—' ?></td><td><span class="status status-approved"><?= h((string)($employee['status']??'PENDING')) ?></span><a class="text-link" href="/reports/payslip?company=<?= rawurlencode($companyId) ?>&run=<?= rawurlencode((string)($run['id']??'')) ?>&employee=<?= rawurlencode((string)($employee['id']??'')) ?>">Payslip</a><?php if(!empty($employee['error_message'])): ?><span class="muted"><?= h((string)$employee['error_message']) ?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>